#!/bin/sh
# Prototype art generation for the Agent World Guild Hall ticket. Each line runs one codex image job.
cd "$(dirname "$0")"
gen() { codex exec -s workspace-write --skip-git-repo-check "Use your image generation tool to create this image, then save the PNG as ./$1.png. Do not edit any other file. Image: $2" > "$1.log" 2>&1; echo "$1 exit $?"; }
STYLE="Original artwork, crisp 16-bit pixel art with a cozy storybook sensibility, warm nostalgic palette (amber, moss green, teal, lavender, peach), clean dark outlines, no text, no logos, no UI, no watermark."
CHAR="Pixel-art game character sprite sheet, 2x2 grid of the SAME character, classic 3/4 top-down RPG view like Stardew Valley, chibi proportions about 1.5 heads tall, full body, facing the camera, on a flat pure magenta #FF00FF background with no shadows on the background and no magenta on the character. Cell order: top-left standing idle; top-right busy working (reading a book or typing on a small laptop held in hands); bottom-left one hand raised with a yellow exclamation mark speech bubble above the head; bottom-right sitting on the floor asleep with a small Zzz. $STYLE"
gen room-iso "Cozy storybook guild hall interior as an isometric diorama cut-away room, warm evening light: arched window with lavender dusk, crowded wooden bookshelves, purple banners, stone fireplace with fire, candles, ivy and hanging plants, notice board with pinned papers, wooden plank floor with a large patterned rug. The middle of the floor is completely empty: no furniture there, no people, no animals. Plain flat dark navy backdrop around the room reaching all four corners. Landscape 3:2. $STYLE" &
gen room-topdown "Cozy storybook guild hall interior in classic 3/4 top-down view like Stardew Valley or Witchbrook interiors, not isometric: the back wall faces the camera straight on at the top, the rectangular floor is seen from above below it. Back wall: tall arched window with lavender dusk, crowded wooden bookshelves, purple banners, stone fireplace with fire, candles, ivy and hanging plants, notice board with pinned papers. Wooden plank floor with a large patterned rug and potted plants in the corners. The middle of the floor is completely empty: no furniture there, no people, no animals. Plain flat dark navy backdrop around the room reaching all four corners. Landscape 3:2. $STYLE" &
gen props "Pixel-art furniture sprite sheet, classic 3/4 top-down view like Stardew Valley, each object separate with generous empty space between them, on a flat pure magenta #FF00FF background with no shadows on the background and no magenta on the objects: a large long wooden table with a parchment map, a glowing purple crystal orb, candles, open books and a teacup; a wooden bench; a green cushioned armchair; a big green beanbag; a small wooden writing desk with quill, papers and a small laptop; a wooden stool; a standing globe. Landscape 3:2. $STYLE" &
gen char-guildmaster "$CHAR The character: an old wise guildmaster wizard with a long white beard, purple robe and pointed purple hat, wooden staff." &
gen char-sage "$CHAR The character: a young sage scholar with round glasses and a blue pointed hat and blue robe." &
gen char-artificer "$CHAR The character: an artificer tinkerer with curly dark hair, goggles on the forehead, teal vest, leather tool belt." &
gen char-sentinel "$CHAR The character: a sentinel guard with dark hair, red scarf, light leather armor and a small round shield on the back." &
gen char-scribe "$CHAR The character: a scribe with blonde hair in a ponytail, green cardigan, carrying a quill behind the ear." &
wait
